import sqlparse
from sqlparse.sql import IdentifierList, Identifier
from sqlparse.tokens import Keyword, DML

# Keywords that introduce another table reference instead of ending the
# FROM part of a statement (e.g. ``FROM foo JOIN bar``).
JOIN_RE = re.compile(
    r'^((LEFT|RIGHT|FULL)\s+)?((INNER|OUTER|STRAIGHT)\s+)?'
    r'((CROSS|NATURAL)\s+)?JOIN$', re.IGNORECASE)


def is_subselect(parsed):
    if not parsed.is_group:
        return False
    for item in parsed.tokens:
        if item.ttype is DML and item.value.upper() == 'SELECT':
            return True
    return False


