    from_seen = False
    for item in parsed.tokens:
        if from_seen:
            if is_subselect(item):
                yield from extract_from_part(item)
            elif item.ttype is Keyword:
                value = ' '.join(item.normalized.split())
                if JOIN_RE.match(value):
                    # A JOIN introduces another table reference, so keep
                    # collecting tokens instead of stopping here.
                    continue
                elif value in ('ON', 'USING'):
                    # Skip the join condition, but don't stop: more
                    # table references may follow.
                    from_seen = False
                    for token in parsed.tokens[
                            parsed.token_index(item) + 1:]:
                        if token.ttype is Keyword and JOIN_RE.match(
                                ' '.join(token.normalized.split())):
                            from_seen = True
                    continue
                return
            else:
                yield item
        elif item.ttype is Keyword and item.normalized.upper() == 'FROM':
            from_seen = True


