"""Helpers for testing.

This mirrors ``tests/conftest.py`` at the project root so that the shared
fixtures are available no matter where the test modules live.  When a test
module sits inside ``tests/``, the fixtures defined there take precedence.
"""

import os

import pytest

ROOT_DIR = os.path.dirname(os.path.abspath(__file__))


def _files_dir():
    """Returns the directory holding the SQL files used by the tests."""
    candidates = (
        os.path.join(ROOT_DIR, 'tests', 'files'),
        os.path.join(ROOT_DIR, 'files'),
    )
    for candidate in candidates:
        if os.path.isdir(candidate):
            return candidate
    return candidates[0]


@pytest.fixture()
def filepath():
    """Returns full file path for test files."""

    def make_filepath(filename):
        return os.path.join(_files_dir(), filename)

    return make_filepath


@pytest.fixture()
def load_file(filepath):
    """Opens filename with encoding and return its contents."""

    def make_load_file(filename, encoding='utf-8'):
        with open(filepath(filename), encoding=encoding) as f:
            return f.read().strip()

    return make_load_file


@pytest.fixture()
def get_stream(filepath):
    def make_stream(filename, encoding='utf-8'):
        return open(filepath(filename), encoding=encoding)

    return make_stream

